    payloadPointer = property(_VSCMGCmdMsgPayload.VSCMGCmdMsg_C_payloadPointer_get, _VSCMGCmdMsgPayload.VSCMGCmdMsg_C_payloadPointer_set)
    headerPointer = property(_VSCMGCmdMsgPayload.VSCMGCmdMsg_C_headerPointer_get, _VSCMGCmdMsgPayload.VSCMGCmdMsg_C_headerPointer_set)

    def _recorder(self, timeDiff=0):
        return _VSCMGCmdMsgPayload.VSCMGCmdMsg_C__recorder(self, timeDiff)


    def recorder(self, timeDiff=0):
        """Create a recorder that keeps this C message's storage owner alive."""
        from Basilisk.architecture.messaging import _msgKeepAlive
        recorder = self._recorder(timeDiff)
        _msgKeepAlive.retainRecorderSource(recorder, self)
        return recorder

    def subscribeTo(self, source):
        """subscribe to another message source"""
        from Basilisk.architecture.messaging import _msgKeepAlive
        if type(source) == type(self):
            VSCMGCmdMsg_C_subscribe(self, source)
        elif type(source) == VSCMGCmdMsg:
            VSCMGCmdMsg_cpp_subscribe(self, source)
        elif type(source) == int: #Note that is assumes it is a uint64_t address in memory
            VSCMGCmdMsg_addr_subscribe(self, source)
            _msgKeepAlive.releaseSource(self)
            return  # a raw address: the caller owns the source, nothing to keep alive
        else:
            raise Exception('tried to subscribe VSCMGCmdMsg to another message type')
    # issue #1433: this Msg_C reader now holds raw pointers into `source`; keep the
    # (otherwise garbage-collectable) source object alive for as long as we read it
        _msgKeepAlive.retainSource(self, source)

    def unsubscribe(self):
        """Unsubscribe to the connected message, noop if no message was connected"""
        from Basilisk.architecture.messaging import _msgKeepAlive
        VSCMGCmdMsg_unsubscribe(self)
    # Clear the native pointers before releasing the source. Source destruction
    # can invoke Python weakref callbacks that re-enter this reader.
        _msgKeepAlive.releaseSource(self)

    def isSubscribedTo(self, source):
        """check if self is subscribed to another message source"""
        if type(source) == type(self):
            return (VSCMGCmdMsg_C_isSubscribedTo(self, source))
